import{_ as r,a0 as s,w as e,s as a,I as n,x as l,a1 as i,A as p,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"適用於所有發行版的 Linux 應用程序——是否真的有好處呢？ | LCTT x X-CMD","titleTemplate":false,"description":"適用於所有發行版的 Linux 應用程序——是否真的有好處呢？ | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"適用於所有發行版的 Linux 應用程序——是否真的有好處呢？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"適用於所有發行版的 Linux 應用程序——是否真的有好處呢？ | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160627 Linux Applications That Works On All Distributions – Are They Any Good","title":"適用於所有發行版的 Linux 應用程序——是否真的有好處呢？","tag":"201609","desc":""},"relativePath":"201609/20160627 Linux Applications That Works On All Distributions – Are They Any Good.md","filePath":"[post].md"}'),d={name:"201609/20160627 Linux Applications That Works On All Distributions – Are They Any Good.md"};function g(x,t,T,f,m,w){const o=s("Link");return e(),a("div",null,[t[21]||(t[21]=n("h1",{id:"適用於所有發行版的-linux-應用程序——是否真的有好處呢",tabindex:"-1"},[l("適用於所有發行版的 Linux 應用程序——是否真的有好處呢？ "),n("a",{class:"header-anchor",href:"#適用於所有發行版的-linux-應用程序——是否真的有好處呢","aria-label":"Permalink to “適用於所有發行版的 Linux 應用程序——是否真的有好處呢？”"},"​")],-1)),t[22]||(t[22]=n("p",null,[n("img",{src:"http://www.iwillfolo.com/wordpress/wp-content/uploads/2016/06/Bundled-applications.jpg",alt:""})],-1)),t[23]||(t[23]=n("p",null,"讓我們回顧一下 Linux 社區最新的願景——推動去中心化的應用來解決發行版的碎片化。",-1)),n("p",null,[t[1]||(t[1]=l("繼上週的文章：“",-1)),i(o,{href:"https://linux.cn/article-7783-1.html"},{default:p(()=>[...t[0]||(t[0]=[l("Snap、Flatpak 這種通吃所有發行版的打包方式真的有用嗎？",-1)])]),_:1}),t[2]||(t[2]=l("” 之後，一系列新觀點浮出水面，其中可能包含關於這樣應用是否有用的重要信息。",-1))]),t[24]||(t[24]=n("h3",{id:"缺點",tabindex:"-1"},[l("缺點 "),n("a",{class:"header-anchor",href:"#缺點","aria-label":"Permalink to “缺點”"},"​")],-1)),n("p",null,[t[5]||(t[5]=l("就這個話題在",-1)),i(o,{href:"http://www.proli.net/2016/06/25/gnulinux-bundled-application-ramblings/"},{default:p(()=>[...t[3]||(t[3]=[l("這裏",-1)])]),_:1}),t[6]||(t[6]=l("的評論，一個叫 Till 的 ",-1)),i(o,{href:"http://www.iwillfolo.com/5-reasons-use-gentoo-linux/"},{default:p(()=>[...t[4]||(t[4]=[l("Gentoo",-1)])]),_:1}),t[7]||(t[7]=l(" 使用者，對於上一次我們未能完全解釋的問題給出了一些新的觀點。",-1))]),t[25]||(t[25]=u('<p>對於上一次我們選擇僅僅稱之為膨脹的的東西，Till 從另一方面做了剖析膨脹將來的發展，這可以幫助我們更好的理解它的組成和其影響。</p><p>這些被稱之為“捆綁應用”的應用程序能夠工作在所有發行版上的機制是——將它依賴的庫都包含在它們的應用軟件之中，Till 説：</p><blockquote><p>“捆綁應用裝載了大量的並不被應用開發者所維護的軟件。如果其中的某個函數庫被發現了一個安全問題而需要更新的話，你得為每一個獨立的應用程序安裝更新來確保你的系統安全。”</p></blockquote><p>本質上，Till 提出了一個<strong>重要的安全問題</strong>。但是它並不僅僅與安全有關係，它還關係到許多方面，比如説系統維護、原子更新等等。</p><p>此外，如果我們進一步假設：依賴的開發者們也許會合作，將他們的軟件與使用它的應用程序一起發佈（一種理想狀況），但這將導致整個平台的開發整體放緩。</p><p>另一個將會導致的問題是<strong>透明的依賴關係變得模糊</strong>，就是説，如果你想知道一個應用程序捆綁了哪些依賴關係，你必須依靠開發者發佈這些數據。</p><p>或者就像 Till 説的：“比如説像某某包是否已經包含了更新的某函數庫這樣的問題將會是你每天需要面對的。”</p><p>與之相反，對於 Linux 現行的標準的包管理方法（包括二進制包和源碼包），你能夠很容易的注意到哪些函數庫已經在系統中更新了。</p><p>並且，你也可以很輕鬆的知道其它哪些應用使用了這個函數庫，這就將你從繁瑣的單獨檢查每一個應用程序的工作中解救了出來。</p><p>其他可能由膨脹導致的缺點包括：<strong>更大的包體積</strong>（每一個應用程序捆綁了依賴），<strong>更高的內存佔用</strong>（沒有共享函數庫），並且，<strong>少了一個包過濾機制</strong>來防止惡意軟件：發行版的包維護者也充當了一個在開發者和用户之間的過濾者，他保障了用户獲得高質量的軟件。</p><p>而在捆綁應用中就不再是這種情況了。</p><p>最後一點，Till 聲稱，儘管在某些情況下很有用，但是在大多數情況下，<strong>捆綁應用程序將弱化自由軟件在發行版中的地位</strong>（專有軟件供應商將被能夠發佈他們的軟件而不用把它放到公共軟件倉庫中）。</p><p>除此之外，它引出了許多其他問題。很多問題都可以簡單歸結到開發人員身上。</p><h3 id="優點" tabindex="-1">優點 <a class="header-anchor" href="#優點" aria-label="Permalink to “優點”">​</a></h3><p>相比之下,另一個名叫 Sven 的人的評論試圖反駁目前普遍反對使用捆綁應用程序的觀點，從而證明和支持使用它。</p><p>“浪費空間？”——Sven 聲稱在當今世界我們有<strong>很多其他事情在浪費磁盤空間</strong>，比如電影存儲在硬盤上、本地安裝等等……</p><p>最終，這些事情浪費的空間要遠遠多於僅僅“ 100 MB 而你每天都要使用的程序。……因此浪費空間的説法實在很荒謬。”</p><p>“浪費運行內存？”——主要的觀點有：</p><ul><li><p><strong>共享庫浪費的內存要遠遠少於程序的運行時數據所佔用的</strong>。</p></li><li><p>而今運行<strong>內存已經很便宜</strong>了。</p></li></ul><p>“安全夢魘”——不是每個應用程序的運行<strong>真正的要注重安全</strong>。</p><p>而且，<strong>許多應用程序甚至從來沒有過任何安全更新</strong>，除非在“滾動更新的發行版”。</p><p>除了 Sven 這種從實用出發的觀點以外，Till 其實也指出了捆綁應用在一些情況下也有着其優點：</p><ul><li>專有軟件的供應商想要保持他們的代碼游離於公共倉庫之外將更加容易。</li><li>沒有被你的發行版打包進去的小眾應用程序將變得更加可行。</li><li>在沒有 Beta 包的二進制發行版中測試應用將變得簡單。</li><li>將用户從複雜的依賴關係中解放出來。</li></ul><h3 id="最後的思考" tabindex="-1">最後的思考 <a class="header-anchor" href="#最後的思考" aria-label="Permalink to “最後的思考”">​</a></h3><p>雖然關於此問題有着不同的想法，但是有一個被大家共同接受的觀點是：<strong>捆綁應用對於填補 Linux 生態系統有着其獨到的作用。</strong></p><p>雖然如此，它的定位，不論是主流的還是邊緣的，都變得愈發清晰，至少理論上是這樣。</p><p>想要儘可能優化其系統的用户，在大多數情況下應該要避免使用捆綁應用。</p><p>而講究易用性、儘可能在維護系統上少費勁的用户，可能應該會感覺這種新應用十分舒爽。</p><hr>',29)),n("p",null,[t[9]||(t[9]=l("via: ",-1)),i(o,{href:"http://www.iwillfolo.com/linux-applications-that-works-on-all-distributions-are-they-any-good/"},{default:p(()=>[...t[8]||(t[8]=[l("http://www.iwillfolo.com/linux-applications-that-works-on-all-distributions-are-they-any-good/",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=l("作者：",-1)),i(o,{href:"http://www.iwillfolo.com/category/editorials/"},{default:p(()=>[...t[10]||(t[10]=[l("Liron",-1)])]),_:1}),t[14]||(t[14]=l(" 譯者：",-1)),i(o,{href:"https://github.com/Chao-zhi"},{default:p(()=>[...t[11]||(t[11]=[l("Chao-zhi",-1)])]),_:1}),t[15]||(t[15]=l(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:p(()=>[...t[12]||(t[12]=[l("wxy",-1)])]),_:1})]),n("p",null,[t[18]||(t[18]=l("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[16]||(t[16]=[l("LCTT",-1)])]),_:1}),t[19]||(t[19]=l(" 原創翻譯，",-1)),i(o,{href:"https://linux.cn/"},{default:p(()=>[...t[17]||(t[17]=[l("Linux中國",-1)])]),_:1}),t[20]||(t[20]=l(" 榮譽推出",-1))])])}const C=r(d,[["render",g]]);export{A as __pageData,C as default};
